import{c as t,Q as r,j as o,m as s}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"Club Registry","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/club-registry.md","filePath":"user/reference/club-registry.md"}'),a={name:"user/reference/club-registry.md"};function n(l,e,i,u,h,d){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="club-registry" tabindex="-1">Club Registry <a class="header-anchor" href="#club-registry" aria-label="Permalink to &quot;Club Registry&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers maintaining the shared list of clubs across events.</p><p>The <em>Club Registry</em> is meshO Manager&#39;s master list of clubs, shared by every event on this server. Enter a club once — its name, short name, and logo — and it&#39;s recognised in every future event, so competitors&#39; club details and logos stay consistent without re-typing.</p><p>It&#39;s one of the stores under <strong>Settings → Global Registry</strong>, alongside the <a href="./competitor-registry">Competitor Registry</a> and the <a href="./../running-the-event/hire-items">Hire card registry</a>.</p><h2 id="why-clubs-are-global" tabindex="-1">Why clubs are global <a class="header-anchor" href="#why-clubs-are-global" aria-label="Permalink to &quot;Why clubs are global&quot;">​</a></h2><p>Clubs live in the registry, not inside a single event. Enter &quot;Red Roos&quot; once and every future event recognises it, with the same short name and logo. Each event keeps its own copy of the clubs its competitors use, merged on top of the shared registry — so a tweak you make for one event doesn&#39;t leak into the others. Because of this, you <strong>add and edit clubs here, not on an event&#39;s Clubs page</strong>. See <a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a>.</p><h2 id="open-the-club-registry" tabindex="-1">Open the Club Registry <a class="header-anchor" href="#open-the-club-registry" aria-label="Permalink to &quot;Open the Club Registry&quot;">​</a></h2><p>In <strong>Settings</strong>, under <strong>Global Registry</strong>, choose <strong>Club Registry</strong>.</p><h2 id="what-s-in-the-list" tabindex="-1">What&#39;s in the list <a class="header-anchor" href="#what-s-in-the-list" aria-label="Permalink to &quot;What&#39;s in the list&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Logo</strong></td><td>The club&#39;s logo, shown on result screens.</td></tr><tr><td><strong>Club</strong></td><td>Full club name. Click it to edit the club.</td></tr><tr><td><strong>Short name</strong></td><td>The abbreviated name used where space is tight.</td></tr><tr><td><strong>Country</strong></td><td>Three-letter country code.</td></tr></tbody></table><p>Use <strong>Search clubs</strong> to filter by full or short name.</p><h2 id="add-and-edit-clubs" tabindex="-1">Add and edit clubs <a class="header-anchor" href="#add-and-edit-clubs" aria-label="Permalink to &quot;Add and edit clubs&quot;">​</a></h2><p>From the <strong>Actions</strong> menu:</p><ul><li><strong>Add club</strong> — enter the club&#39;s name, short name, and country.</li></ul><p>Click a club&#39;s name to edit its <strong>short name</strong>, <strong>country</strong>, and <strong>logo</strong> — upload your own image to override the default. You can also delete a club from the edit dialog.</p><h2 id="populate-from-eventor" tabindex="-1">Populate from Eventor <a class="header-anchor" href="#populate-from-eventor" aria-label="Permalink to &quot;Populate from Eventor&quot;">​</a></h2><p>If you use Eventor, the <strong>Actions</strong> menu can fill the registry for you. Both need your Eventor connection configured under <strong>Settings → Eventor</strong>:</p><ul><li><strong>Refresh clubs from Eventor</strong> — pull the known-clubs list for your organisation.</li><li><strong>Fetch default logos from Eventor</strong> — download each club&#39;s logo automatically. A progress bar shows how many have been fetched.</li></ul><blockquote><p><strong>Tip:</strong> A club&#39;s <strong>short name</strong> is what most screens display, so set it to something that reads well at a glance — and upload a logo if you want the club&#39;s icon to appear alongside results.</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a> — how clubs attach to competitors in an event</li><li><a href="./competitor-registry">Competitor Registry</a> — the matching store for people</li><li><a href="./../screens/creating-screens">Creating screens</a> — where club names and logos appear</li><li><a href="./settings">Settings</a></li></ul>',21)])])}const b=t(a,[["render",n]]);export{g as __pageData,b as default};
